import{_ as o,a as r,b as e}from"./chunks/notes-toolbar-tags.Dzi-MWtb.js";import{_ as a,o as d,c as n,a2 as l}from"./chunks/framework.Dx-TCpNt.js";const f=JSON.parse('{"title":"笔记","description":"笔记是分格与对齐存在的理由。一条笔记可以挂在整页，也可以挂在某一格；它用 Markdown 编写，能带标签、来源和附图。","frontmatter":{"description":"笔记是分格与对齐存在的理由。一条笔记可以挂在整页，也可以挂在某一格；它用 Markdown 编写，能带标签、来源和附图。"},"headers":[],"relativePath":"zh/guide/notes.md","filePath":"zh/guide/notes.md","lastUpdated":1794814645000}'),i={name:"zh/guide/notes.md"};function s(c,t,g,h,p,u){return d(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h1><p>笔记是分格与对齐存在的理由。一条笔记可以挂在整页，也可以挂在某一格；它用 Markdown 编写，能带标签、来源和附图。</p><figure class="shot"><img src="'+o+'" alt="笔记栏：Markdown 编辑器、实时预览、标签与总览标签页"><figcaption>笔记栏位于舞台右侧，可以收起。编辑器上方的工具栏用于插入 Markdown；标签栏在“本页”和全局总览之间切换。</figcaption></figure><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>像“这版翻译丢了敬语”这样的记录，一旦脱离它所指的对话框就失去意义。这里的笔记挂在页面或分格 id 上，因此能经受页面重排、模板变更和导出。第二个问题是检索：翻过五十页之后，你得把打了 <code>语气</code> 标签的笔记、或来自某一篇文章的笔记全部找出来。</p><h2 id="页面笔记与格级笔记" tabindex="-1">页面笔记与格级笔记 <a class="header-anchor" href="#页面笔记与格级笔记" aria-label="Permalink to &quot;页面笔记与格级笔记&quot;">​</a></h2><table tabindex="0"><thead><tr><th>范围</th><th>何时使用</th><th>存储为</th></tr></thead><tbody><tr><td><strong>页面</strong></td><td>整体观察、校对意见、关于某一页的疑问。</td><td><code>scope: &quot;page&quot;</code>、<code>panelId: null</code></td></tr><tr><td><strong>分格</strong></td><td>措辞、语气、某个对话框、翻译差异。</td><td><code>scope: &quot;panel&quot;</code>、<code>panelId: &quot;&lt;panel id&gt;&quot;</code></td></tr></tbody></table><p>在工作台或对照阅读中选中一个分格，下一条笔记就会限定到该分格。没有选中时，笔记是页面级。编辑器占位文字会说明当前作用域：<em>记录这一格的原文……</em> 还是 <em>记录整页的观察……</em>。</p><h2 id="笔记类型" tabindex="-1">笔记类型 <a class="header-anchor" href="#笔记类型" aria-label="Permalink to &quot;笔记类型&quot;">​</a></h2><p>一页或一格可以有很多条笔记，每条笔记都有类型。内置类型是 <strong>背景知识</strong>、<strong>生词</strong> 和 <strong>吐槽</strong>。一个项目启用多种语言时，每种启用的语言还会各有一个类型（例如 <strong>日语</strong> 或 <strong>中文</strong>）；禁用的语言不会出现。</p><p>笔记栏的顺序是 筛选 → 列表 → 编辑器。笔记按类型分组显示，<strong>全部</strong> 筛选会显示所有分组。点一个类型标签或 <strong>添加笔记</strong>，会以该类型开始一条新笔记，并把焦点移到列表下方的编辑器；草稿已经有内容时，点类型只会改这条草稿的类型。</p><p>自定义类型可以在类型行里新增、改名、换色和删除。它们存放在 <code>data/library.json</code> 的 <code>noteTypes</code> 中，因此跟着库走，而不是跟着某个浏览器配置。删掉某个类型后，仍在引用它的笔记会回落到背景知识。</p><p>在类型功能出现之前保存的笔记会迁移到背景知识。页面文档升到 <code>schemaVersion: 2</code>，原来的版本 1 文件会以 <code>&lt;file&gt;.v1.bak</code> 留在旁边（例如 <code>3.json.v1.bak</code>）。</p><p>格子详情页内嵌同一个编辑器，因此不用离开当前页就能写本格笔记。切格、翻页或返回之前，草稿会先落盘。</p><h2 id="写一条笔记" tabindex="-1">写一条笔记 <a class="header-anchor" href="#写一条笔记" aria-label="Permalink to &quot;写一条笔记&quot;">​</a></h2><figure class="shot"><img src="'+r+'" alt="笔记编辑器：Markdown 工具栏、编辑 / 分栏 / 预览切换、来源与标签输入框、暂存区"><figcaption>笔记编辑器：Markdown 工具栏、编辑 / 分栏 / 预览、来源和标签输入框，下面是暂存区。编辑器上方的范围提示说明下一条笔记属于整页还是某个分格。</figcaption></figure><ol><li>在列表上方选一个类型标签，或点击 <strong>添加笔记</strong>。焦点会落到列表下方的编辑器；草稿已有内容时，点类型只改变这条草稿的类型。</li><li>输入 Markdown。工具栏会插入常用语法：</li></ol><table tabindex="0"><thead><tr><th>按钮</th><th>插入</th></tr></thead><tbody><tr><td><strong>B</strong></td><td>加粗（<code>Ctrl+B</code>）</td></tr><tr><td><em>I</em></td><td>斜体（<code>Ctrl+I</code>）</td></tr><tr><td>• 列表</td><td>无序列表</td></tr><tr><td>❝ 引用</td><td>引用块</td></tr><tr><td><code>&lt;/&gt;</code></td><td>行内代码</td></tr><tr><td>↗ 链接</td><td>链接（<code>Ctrl+K</code>）</td></tr><tr><td>H</td><td>标题</td></tr><tr><td>S</td><td>删除线</td></tr><tr><td>1.</td><td>有序列表</td></tr><tr><td>—</td><td>分割线</td></tr></tbody></table><ol start="3"><li>选择模式：<strong>编辑</strong>、<strong>分栏</strong>（编辑器 + 预览）或 <strong>预览</strong>。</li><li>按 <code>Ctrl+Enter</code> 或点击 <strong>添加笔记</strong>。</li></ol><p>渲染输出会转义原始 HTML；HTML 永远不会被执行。在支持 Markdown 之前写的笔记仍按纯文本加换行渲染。</p><h2 id="标签" tabindex="-1">标签 <a class="header-anchor" href="#标签" aria-label="Permalink to &quot;标签&quot;">​</a></h2><ul><li>输入标签后按 <code>Enter</code> 添加。</li><li>标签以数组形式存储在笔记上。</li><li>用量会在所有页面中汇总并作为建议提供，<strong>筛选</strong> 行可以按标签筛选当前页。</li></ul><p>标签是构建个人分类体系最省力的方式：<code>语气</code>、<code>误译</code>、<code>文化</code>、<code>待确认</code>、<code>拟声词</code>。</p><h2 id="附图" tabindex="-1">附图 <a class="header-anchor" href="#附图" aria-label="Permalink to &quot;附图&quot;">​</a></h2><p>笔记可以带截图——适合记录参考页、版本对照，或那本你懒得扫的纸质书照片。</p><ul><li>把图片<strong>粘贴</strong>到编辑器，或<strong>拖放</strong>到笔记表单。</li><li><strong>添加图片</strong> 打开文件选择器；每张附图都有缩略图和移除按钮。</li><li>小于 400 KB 的图片按原样存储（data URL）。更大的图片会缩放到最长边 1600 px，再以质量 0.85 重新编码为 WebP。</li><li>图片存放在页面 JSON 中笔记的 <code>images</code> 数组里，因此会随页面一起进入导出和工程文件。图片太多会让 JSON 变大；宁可用几张裁剪后的参考图，也不要用整页图。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>每条笔记都可以带一个来源：</p><ul><li><strong>URL</strong> —— 粘贴链接。笔记正文中的第一个 URL 会自动填入。<strong>抓标题</strong> 会尝试读取页面标题，超时 5 秒；如果抓取被拦截，请手动输入标题。</li><li><strong>自由文本</strong> —— 例如 <code>ChatGPT 对话 2026-05-12</code>、书名或访谈名称。</li></ul><p>来源显示在笔记下方，可用 <strong>收起来源</strong> 切换显示。</p><h2 id="复制给大模型的上下文" tabindex="-1">复制给大模型的上下文 <a class="header-anchor" href="#复制给大模型的上下文" aria-label="Permalink to &quot;复制给大模型的上下文&quot;">​</a></h2><p><strong>复制本页上下文</strong> / <strong>复制上下文</strong> 会从当前页、选中的分格、笔记正文、标签和来源拼出一段提示词。</p><ul><li>复制对话框有一个可编辑的 <strong>模板前缀</strong>。</li><li>支持的占位符：<code>{volume}</code>、<code>{chapter}</code>、<code>{page}</code>、<code>{panel}</code>、<code>{notes}</code>、<code>{text}</code>、<code>{tags}</code>。</li><li>对模板的修改会自动记住。</li><li><strong>预览</strong> 显示将要复制的确切内容；<strong>复制</strong> 把它放进剪贴板。</li></ul><p>默认模板会要求模型解释语言点、语气和文化背景，并指出理解错误。按你偏好的讲解风格调整一次，之后每次复制都会沿用。</p><h2 id="总览与搜索" tabindex="-1">总览与搜索 <a class="header-anchor" href="#总览与搜索" aria-label="Permalink to &quot;总览与搜索&quot;">​</a></h2><p><strong>总览 / 搜索</strong> 标签页在整个图库范围内工作，而不只是当前页：</p><ul><li>搜索笔记正文、标签和来源。</li><li>按卷、话、页码、标签或来源筛选。</li><li>按话、标签或来源聚合结果。</li><li>结果上方会显示命中了多少条笔记、覆盖多少页。</li><li>点击结果跳转到该页；笔记如果是格级，还会跳到该分格。</li></ul><p><strong>清除筛选</strong> 重置当前查询。</p><h2 id="暂存区" tabindex="-1">暂存区 <a class="header-anchor" href="#暂存区" aria-label="Permalink to &quot;暂存区&quot;">​</a></h2><p>暂存区用来接住那些还没想好归属的想法——脑内的页边空白。</p><ol><li>在 <strong>随手记暂存</strong> 中输入，按 <code>Ctrl+Enter</code> 或点击 <strong>记下</strong>。</li><li>之后用 <strong>归到本页</strong> 或 <strong>归到本格</strong> 把它变成正式笔记。</li></ol><h2 id="编辑与删除" tabindex="-1">编辑与删除 <a class="header-anchor" href="#编辑与删除" aria-label="Permalink to &quot;编辑与删除&quot;">​</a></h2><p>每条已保存的笔记都有 <strong>编辑</strong>、<strong>复制上下文</strong>、<strong>按标签筛选</strong> 和删除操作。笔记上的 <strong>渲染 / 源码</strong> 开关在渲染后的 Markdown 和原始文本之间切换。删除分格会删除它的格级笔记，因此想与版式解耦的内容请用页面笔记。</p><p>编辑已有笔记时，内容会直接装进笔记栏顶部那一个编辑器，不会在笔记卡片里再展开一个 Markdown 编辑区：</p><ul><li>编辑器上方出现 <strong>正在编辑已有笔记</strong> 的提示和 <strong>取消</strong> 按钮；取消会清空编辑器，原笔记保持不变。</li><li>提交按钮由 <strong>添加笔记</strong> 变成 <strong>保存修改</strong>。</li><li>编辑期间 <strong>整页 / 分格</strong> 作用域开关被锁定，避免保存时把笔记挪到另一个作用域。</li><li>被编辑的笔记卡片会高亮；删除这条正在编辑的笔记等同于取消编辑。</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>笔记跑到了错误的作用域。</strong> 检查编辑器上方那句话：它要么写出格号，要么写着<em>整页</em>。取消选中分格即可写页面笔记。</li><li><strong><code>Ctrl+Enter</code> 没反应。</strong> 焦点必须在笔记编辑器内；在搜索框中不会触发该快捷键。</li><li><strong>粘贴的截图太大。</strong> 超过限制的图片会自动缩小，但整页截图仍然很重；先裁剪。</li><li><strong>标签筛选隐藏了笔记。</strong> <strong>筛选</strong> 行是按页生效的，与总览的筛选不是一回事。</li><li><strong>文字看起来像代码。</strong> 围栏代码块的首尾两行各要三个反引号。</li></ul><figure class="shot"><img src="'+e+'" alt="笔记编辑器：整页与分格范围切换、Markdown 工具栏、实时预览、附件缩略图与标签输入行"><figcaption>笔记编辑器：整页 / 分格范围、Markdown 工具栏、实时预览、附件缩略图与标签输入行。</figcaption></figure><h2 id="缺失的截图" tabindex="-1">缺失的截图 <a class="header-anchor" href="#缺失的截图" aria-label="Permalink to &quot;缺失的截图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>图</th><th>用于</th></tr></thead><tbody><tr><td>总览搜索</td><td>筛选、聚合与跳转到页面</td></tr><tr><td>复制上下文对话框</td><td>模板前缀与预览</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/zh/guide/compare">对照阅读</a> —— 大多数笔记在这里产生。</li><li><a href="/KomaYomi-docs/zh/guide/export">导出</a> —— 笔记如何变成学习文档。</li><li><a href="/KomaYomi-docs/zh/guide/shortcuts">键盘快捷键</a> —— 编辑器与全局按键。</li></ul>',52)])])}const q=a(i,[["render",s]]);export{f as __pageData,q as default};
